package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Node struct {
	k    int
	l, r *Node
}

func insert(n *Node, x int) (*Node, bool) {
	if n == nil {
		return &Node{k: x}, true
	}
	var ok bool
	if x < n.k {
		n.l, ok = insert(n.l, x)
	} else if x > n.k {
		n.r, ok = insert(n.r, x)
	}
	return n, ok
}

func del(n *Node, x int) (*Node, bool) {
	if n == nil {
		return nil, false
	}
	var ok bool
	if x < n.k {
		n.l, ok = del(n.l, x)
		return n, ok
	}
	if x > n.k {
		n.r, ok = del(n.r, x)
		return n, ok
	}
	if n.l == nil {
		return n.r, true
	}
	if n.r == nil {
		return n.l, true
	}
	s := n.r
	for s.l != nil {
		s = s.l
	}
	n.k = s.k
	n.r, _ = del(n.r, s.k)
	return n, true
}

func height(n *Node) int {
	if n == nil {
		return 0
	}
	a, b := height(n.l), height(n.r)
	if a > b {
		return a + 1
	}
	return b + 1
}

func walk(n *Node, out *[]string) {
	if n == nil {
		return
	}
	walk(n.l, out)
	*out = append(*out, strconv.Itoa(n.k))
	walk(n.r, out)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	var root *Node
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		var x int
		if len(f) > 1 {
			x, _ = strconv.Atoi(f[1])
		}
		switch f[0] {
		case "insert":
			var ok bool
			root, ok = insert(root, x)
			if ok {
				fmt.Fprintln(w, "ok")
			} else {
				fmt.Fprintln(w, "dup")
			}
		case "contains":
			n := root
			for n != nil && n.k != x {
				if x < n.k {
					n = n.l
				} else {
					n = n.r
				}
			}
			if n != nil {
				fmt.Fprintln(w, "yes")
			} else {
				fmt.Fprintln(w, "no")
			}
		case "delete":
			var ok bool
			root, ok = del(root, x)
			if ok {
				fmt.Fprintln(w, "ok")
			} else {
				fmt.Fprintln(w, "missing")
			}
		case "inorder":
			var o []string
			walk(root, &o)
			if len(o) == 0 {
				fmt.Fprintln(w, "<empty>")
			} else {
				fmt.Fprintln(w, strings.Join(o, " "))
			}
		case "height":
			fmt.Fprintln(w, height(root))
		case "min", "max":
			if root == nil {
				fmt.Fprintln(w, "empty")
				break
			}
			n := root
			for {
				nx := n.l
				if f[0] == "max" {
					nx = n.r
				}
				if nx == nil {
					break
				}
				n = nx
			}
			fmt.Fprintln(w, n.k)
		}
	}
}

